{
  "title": "CSCI-603: Computational Problem Solving Foundations",
  "learningObjectives": [
    "Identify and articulate the core components of a computational problem statement including inputs, outputs, and constraints.",
    "Apply recursive decomposition to solve problems by defining base cases and reducing complex instances to simpler sub-problems.",
    "Evaluate the correctness of an algorithm through systematic testing, tracing, and debugging of boundary and error cases."
  ],
  "beats": [
    {
      "title": "Defining the Computational Problem",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "A student must write a function that takes a list of integers and returns the sum of all even numbers, clearly defining the input format and expected output before writing any code.",
      "visualDirection": "Display a structured template with labeled sections for 'Problem Statement', 'Input Specification', 'Output Specification', and 'Constraints' to guide the learner in drafting their own problem definition.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-603"]
    },
    {
      "title": "Decomposing with Functions",
      "claim": "Functions decompose a solution into named operations with parameters and results, allowing complex tasks to be broken into manageable units.",
      "example": "To calculate the average of a dataset, one function reads the input, a second function filters out non-numeric values, and a third computes the mean, each with clear parameters and return values.",
      "visualDirection": "Show a flowchart where a large 'Compute Average' block branches into three smaller, labeled blocks: 'Read Input', 'Filter Data', and 'Calculate Mean', illustrating functional decomposition.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Understanding Recursion",
      "claim": "Recursion solves a problem through smaller instances and requires a base case to terminate the process.",
      "example": "Calculating the factorial of 5 involves calling the function with 4, then 3, down to 1 (the base case), where the result is returned without further recursive calls.",
      "visualDirection": "Render a tree diagram where the root node is 'Factorial(5)' and each child node represents a recursive call (e.g., 'Factorial(4)'), terminating at leaf nodes labeled 'Base Case: n=1'.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Elementary Data Structures: Lists",
      "claim": "Lists represent ordered sequences, providing a fundamental way to store and access collections of items in a specific order.",
      "example": "A student's grade list [85, 90, 78, 92] allows sequential access to each score and supports operations like appending a new grade or removing the lowest one.",
      "visualDirection": "Present a horizontal array graphic with numbered indices above each element, highlighting the ordered nature of the list and demonstrating an 'append' action adding a new value at the end.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Elementary Data Structures: Trees",
      "claim": "Trees represent hierarchy, organizing data in parent-child relationships that naturally model nested or branching structures.",
      "example": "A file system directory structure is a tree where the root is the main drive, branches are folders, and leaves are individual files, enabling efficient traversal and organization.",
      "visualDirection": "Draw a binary tree with a root node labeled 'Root', two child nodes labeled 'Left' and 'Right', and further descendants to visually demonstrate hierarchical nesting.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-603"]
    },
    {
      "title": "Elementary Data Structures: Graphs",
      "claim": "Graphs represent connected entities, modeling relationships between objects where nodes are entities and edges denote connections.",
      "example": "A social network graph connects users as nodes and friendships as edges, allowing algorithms to find the shortest path between two people or identify communities.",
      "visualDirection": "Illustrate a network of circles (nodes) linked by lines (edges), with one node highlighted to show its connections, emphasizing the relational aspect of graphs.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-603"]
    },
    {
      "title": "Algorithmic Invariants and Correctness",
      "claim": "Correctness arguments rely on invariants—conditions that remain true throughout an algorithm's execution—to prove that the solution meets its specification.",
      "example": "In a sorting algorithm, the invariant 'the subarray to the left of the current index is sorted' holds true after each iteration, guaranteeing the final array is fully sorted.",
      "visualDirection": "Show a timeline of a loop with a highlighted invariant statement persisting across iterations, visually reinforcing that the condition is maintained throughout the process.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Debugging and Testing Strategies",
      "claim": "Debugging separates syntax, runtime, and logical failures, while testing compares intended behavior with observable results, including boundary and error cases.",
      "example": "A tester runs a function with an empty list (boundary case) and a list containing only negative numbers (error case) to verify the program handles these scenarios without crashing.",
      "visualDirection": "Display a split-screen view: one side shows a code snippet with a syntax error highlighted, the other shows a test case output indicating a logical failure, illustrating the debugging workflow.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Pseudo-code to Implementation",
      "claim": "Assignments require expressing algorithms first in pseudo-code to clarify logic before translating into a specific programming language like Python.",
      "example": "A student writes a step-by-step pseudo-code description of a binary search algorithm, then converts each step into Python syntax, ensuring the logic remains unchanged.",
      "visualDirection": "Present a side-by-side comparison: the left column contains high-level pseudo-code steps, and the right column shows the corresponding Python code lines, with arrows linking matching operations.",
      "sourceIds": ["rit-csci-603", "python-language-reference"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Before finalizing any solution, verify that the problem statement is precise, the chosen data structures match the requirements, recursion has a clear base case, and tests cover in",
      "example": "A checklist item asks: 'Does the algorithm handle the edge case where the input list is empty?' followed by 'Are all recursive calls reducing the problem size?'",
      "visualDirection": "Render a compact checklist graphic with four tick-box items: 'Precise Problem Statement', 'Appropriate Data Structures', 'Valid Recursive Base Case', and 'Comprehensive Test Coverage', each with a brief prompt.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-603"]
    }
  ]
}
